                          {
                            "type": "number"
                          },
                          {
                            "pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$",
                            "type": "string"
                          }
                        ],
                        "decimal_places": 30,
                        "description": "Exact decimal string or integer; float and bool are rejected",
                        "ge": 0,
                        "max_digits": 60
                      },
                      {
                        "type": "null"
                      }
                    ],
                    "default": null,
                    "title": "Unit Cost"
                  }
                },
                "required": [
                  "label"
                ],
                "title": "CostLine",
                "type": "object"
