                "items": {
                  "enum": [
                    "currency",
                    "observed_on",
                    "price_type",
                    "includes_tax",
                    "includes_shipping",
                    "channel",
                    "region"
                  ],
                  "type": "string"
                },
                "title": "Group By",
                "type": "array"
              },
              "price_points": {
                "items": {
                  "$ref": "#/$defs/PricePoint"
                },
                "title": "Price Points",
                "type": "array"
              },
              "quantiles": {
                "items": {
                  "anyOf": [
                    {
                      "type": "number"
                    },
                    {
                      "pattern": "^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$",
                      "type": "string"
                    }
                  ],
                  "decimal_places": 30,
                  "description": "Exact decimal string or integer; float and bool are rejected",
                  "ge": 0,
                  "le": 1,
                  "max_digits": 60
                },
                "title": "Quantiles",
                "type": "array"
              },
              "target_currency": {
                "anyOf": [
                  {
                    "pattern": "^[A-Z]{3}$",
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "default": null,
                "title": "Target Currency"
              }
            },
            "required": [
              "price_points"
            ],
            "title": "PriceBandInput",
            "type": "object"
          }
        },
